	a = httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path == "/mid" {
			http.Redirect(w, r, bs.URL+"/away", http.StatusFound)
			return
		}
		if r.URL.Path == "/back" {
			serveBoth(w, r)
